// Helper function to count lower-case letters with odd order in the alphabet
method CountLowerCaseOdd(txt: string) returns (count: int)
    requires txt != null
    ensures count >= 0
{
    count := 0;
    var i := 0;
    while i < txt.Length
        invariant 0 <= i <= txt.Length
        invariant count >= 0
    {
        if txt[i] >= 'a' && txt[i] <= 'z' && (txt[i] - 'a') % 2 == 1 {
            count := count + 1;
        }
        i := i + 1;
    }
}
